import type { components } from './schema';

/**
 * Names for the shapes in `schema.ts`.
 *
 * **`schema.ts` is generated by `openapi-typescript` and never edited**, and
 * `api/openapi.yaml` says the contract "is hand-written and comes before the
 * handlers". A hand-written mirror of it here would be a second copy that
 * diverges on the first edit, so this file contains no shapes: every line is an
 * alias, and `pnpm run check:api` fails if the generated file is stale.
 *
 * What this file is for is the indexing. `components['schemas']['Cluster']`
 * written at forty call sites is forty places to update when a schema is
 * renamed, and it does not read.
 */
type Schemas = components['schemas'];

// The envelope vocabulary.
export type State = Schemas['State'];
export type ReasonCode = Schemas['ReasonCode'];
export type Reason = Schemas['Reason'];
export type Remedy = Schemas['Remedy'];
export type Scope = Schemas['Scope'];

// Failures that are not answers.
export type Problem = Schemas['Problem'];

// Session and profile.
export type LoginRequest = Schemas['LoginRequest'];
export type Session = Schemas['Session'];
export type SignInMethods = Schemas['SignInMethods'];
export type SingleSignOn = Schemas['SingleSignOn'];
export type Capabilities = Schemas['Capabilities'];

// Clusters, navigation, extensions.
export type Cluster = Schemas['Cluster'];
export type ClusterColour = Schemas['ClusterColour'];
export type Ref = Schemas['Ref'];
export type NavGroup = Schemas['NavGroup'];
export type NavMenu = Schemas['NavMenu'];
export type NavDiscovery = Schemas['NavDiscovery'];
/** Whether each kind of a cluster's menu holds an object the person may see,
 *  by slug (`kindOfHref` of its entry's href). */
export type NavOccupancy = Schemas['NavOccupancy'];
export type KindOccupancy = Schemas['KindOccupancy'];

/**
 * The server's view of one extension on one cluster.
 *
 * Named `ExtensionInfo` and not `Extension` because `../extension.ts` already
 * owns that name for the *bundle's* half of the contract - the routes and the
 * nav entry a build carries. The two meet by `key`, which is the same string on
 * both sides and in Go, and keeping them distinguishable in an import list is
 * worth the four characters.
 */
export type ExtensionInfo = Schemas['Extension'];
/** An extension that is off on a cluster that runs what it reads */
export type ExtensionSuggestion = Schemas['ExtensionSuggestion'];

export type Preferences = Schemas['Preferences'];
/** One person's choices about the kinds column. */
export type KindPreferences = Schemas['KindPreferences'];
export type RailTileWrite = Schemas['RailTileWrite'];
export type RailMoveWrite = Schemas['RailMoveWrite'];
export type RailPlaceWrite = Schemas['RailPlaceWrite'];
export type RailNameplateWrite = Schemas['RailNameplateWrite'];
export type RailBarWrite = Schemas['RailBarWrite'];

/**
 * The resource list, and the shapes the grid draws.
 *
 * `ListPageEnvelope` is a **value** envelope and not a list one, which is the
 * single most consequential line of the contract for the list page: a kind with
 * nothing in it is `ok` with `data.rows: []` **and** `data.columns` filled, so
 * the grid still has its headings. `empty` on that envelope would mean there was
 * no page at all. The page's own empty state therefore lives inside the `ok`
 * arm and is drawn by the grid, never by a notice that replaces it.
 */
export type ListPage = Schemas['ListPage'];
export type Column = Schemas['Column'];
export type Row = Schemas['Row'];
export type Cell = Schemas['Cell'];
export type Reading = Schemas['Reading'];
export type BulkAffordance = Schemas['BulkAffordance'];
/** Whether the list's "+" may create an object of its kind */
export type CreateAffordance = Schemas['CreateAffordance'];
export type CreateTemplate = Schemas['CreateTemplate'];
/** An operator an extra page reads from, as the console would install it. */
export type Prereq = Schemas['Prereq'];
export type PrereqChart = Schemas['PrereqChart'];
export type PrereqArgo = Schemas['PrereqArgo'];
export type PrereqHelm = Schemas['PrereqHelm'];

/**
 * One object, in the shape the drawer draws.
 *
 * A **value** envelope: an object that is not there is `absent`, not `empty`.
 * `api/errors.md` is explicit that a single thing has no empty arm, and the
 * drawer is the surface where the difference is loudest — a pod deleted while
 * its panel was open is gone, not blank.
 */
export type DetailPage = Schemas['DetailPage'];
export type DetailSection = Schemas['DetailSection'];
export type ManifestPanel = Schemas['ManifestPanel'];
export type MetricsPanel = Schemas['MetricsPanel'];
export type DataPanel = Schemas['DataPanel'];
export type DataEntry = Schemas['DataEntry'];
export type DataWrite = Schemas['DataWrite'];
export type ChangesPanel = Schemas['ChangesPanel'];
/** One event about one object, as the object's own panel draws it. Not
 *  `EventEntry`, which is the cluster page's row: that one answers *what is
 *  happening across this cluster* and carries a destination, and this one answers
 *  *what happened to the object already on screen*. */
export type ObjectEvent = Schemas['ObjectEvent'];
export type ManifestLine = Schemas['ManifestLine'];
export type ManifestToken = Schemas['ManifestToken'];
export type ManifestWrite = Schemas['ManifestWrite'];
export type ConfirmationPlan = Schemas['ConfirmationPlan'];
export type PlanFacts = Schemas['PlanFacts'];
export type ActOutcome = Schemas['ActOutcome'];
export type PlanTarget = Schemas['PlanTarget'];
/** One verb offered on an object. **Derived from `DetailPage` rather than named
 *  in `components/schemas`**, because the contract declares it inline there -
 *  so this alias moves when the contract does and cannot name a shape that is no
 *  longer in it. */
export type DetailAction = NonNullable<Schemas['DetailPage']['actions']>[number];
/** Whether a pod's page draws Shell, under `shared`. Derived from `DetailPage`
 *  for `DetailAction`'s reason. */
export type ShellOffer = NonNullable<Schemas['DetailPage']['shell']>;
export type Confirmation = Schemas['Confirmation'];
/** One labeled fact. Named apart from `DetailSection['fields']` because the
 *  generated type spells that inline and forty call sites cannot index it. */
export type DetailField = NonNullable<DetailSection['fields']>[number];
/** A drawer tab as data rather than as a branch or a bare URL string, which
 *  could point at a page that is not installed. As data it degrades by being
 *  absent. */
export type Tab = Schemas['Tab'];
/** Another object this one points at, and why. `linkable` is the server's answer
 *  and is read, never re-derived - see `pages/object/Relations.tsx`. */
export type Relation = Schemas['Relation'];
/** Whether the reverse walk ran, completed and found anything - on a ConfigMap
 *  and a Secret, absent everywhere else. The referrers are `relations` rows
 *  under the role `Used by`; this is the *answer*. A member of its own because
 *  "walked and found nothing" is the majority case on those two kinds, is what
 *  an operator deletes an object on, and must render as neither silence nor a
 *  refusal - see `pages/object/Relations.tsx`. */
export type UsedBy = Schemas['UsedBy'];

/**
 * What a pod is made of.
 *
 * `PodContainer` and not `Container`: the contract already has a `Container`,
 * and it is a different thing - `{name, init, ready, restarts}` for the log
 * picker. Two shapes with one name is a payload whose members are half absent
 * depending on who asked.
 */
export type PodContainer = Schemas['PodContainer'];
/**
 * One of a container's three probes, as declared.
 *
 * Always three per container, always in the order liveness, readiness, startup.
 * **The absent ones are not filtered out** and must not be: "no readiness probe"
 * is a finding, because a Service can be sending traffic to a container nothing
 * has ever asked whether it is ready, and an empty area is not that sentence.
 */
export type ContainerProbe = Schemas['ContainerProbe'];
/** Whether a probe is declared, **as a kind rather than as a missing field**.
 *  `absent` is a fact about the pod and `unreadable` is a fact about this
 *  console; drawing them alike sends somebody to fix the wrong one. */
export type ProbeState = Schemas['ProbeState'];
/** What the kubelet last reported about a container. Always present, carrying
 *  `unreported` where nothing was said. */
export type ContainerStatus = Schemas['ContainerStatus'];
/** `unreported` is not "not ready": every container of a Pending pod is in it,
 *  and nothing has run a readiness check to fail. */
export type ContainerRunState = Schemas['ContainerRunState'];
export type EnvVar = Schemas['EnvVar'];
export type EnvImport = Schemas['EnvImport'];
export type EnvSource = Schemas['EnvSource'];
/** Why there is no value on a row, **as a kind rather than as a sentence**. Four
 *  of them, and the pair that gets folded together is the pair that matters. */
export type EnvAbsence = Schemas['EnvAbsence'];
export type ResourceAmount = Schemas['ResourceAmount'];
/** One revealed value. It arrives through the one door that reveals and is never
 *  in a panel payload. */
export type EnvValue = Schemas['EnvValue'];

/** What the TLS material in a Secret or a ConfigMap says. One card per
 *  certificate and not per key: `tls.crt` routinely holds a leaf plus its
 *  intermediates. */
export type CertificateSet = Schemas['CertificateSet'];
export type CertificateBundle = Schemas['CertificateBundle'];
export type Certificate = Schemas['Certificate'];
/** What a Role or a ClusterRole grants, with its own state: a Role that grants
 *  nothing and a Role whose rules could not be read are different answers, and
 *  on a permissions surface they must not render the same. `forbidden` arrives
 *  at the envelope instead — reading the rules is reading the object. */
export type RuleSet = Schemas['RuleSet'];
/** One rule of a Role. `wildcards` and `wildcardTone` arrive already graded, by
 *  the same rule the Access Control grid uses: re-deriving them here would be a
 *  second judgment that disagrees with the grid about the same Role. */
export type PolicyRule = Schemas['PolicyRule'];
/** An address a person can open. Ingresses have them and nothing else does. */
export type ObjectURL = Schemas['ObjectURL'];
/** One port an object exposes. `forwardable` arrives already decided, with a
 *  `reason` where it is false: deriving it from `protocol` here would be a
 *  second copy of a rule the server enforces, and the copy that offers a button
 *  the server then refuses. */
export type ObjectPort = Schemas['ObjectPort'];
/** What an object says when the object **is** an Event. Not one of
 *  `DetailPage.events`, which are the events *about* it: on an Event those two
 *  are different things, and the panel that showed only the second is why this
 *  exists. */
export type EventSubject = Schemas['EventSubject'];

/** One entry of the selector every list page carries. `state` is present only
 *  where the console knows one namespace's own state, which is unusual: the list
 *  is read in one call and every name in it was read the same way. */
export type Namespace = Schemas['Namespace'];

// --- The dock ------------------------------------------------------------------

/** One container of a pod that can be followed, for the log panel's switcher.
 *  Not `PodContainer`, which is the object page's much larger shape - see the
 *  note there. `restarts` is the only thing in the browser that can tell whether
 *  a previous run exists, because an EventSource cannot read the 404 the server
 *  would otherwise answer with. */
export type Container = Schemas['Container'];

/** One event of the log stream. `state` carries the envelope's five-state
 *  vocabulary mid-stream, which is the only way a log that stopped because the
 *  pod was deleted reads differently from one that stopped because nothing is
 *  being written. */
export type LogEvent = Schemas['LogEvent'];

/**
 * One page backwards: the block of lines immediately preceding what the pane
 * already holds, oldest first.
 *
 * `stop` is the member the pane branches on, and it is three values rather than
 * a boolean because *there is nothing older*, *there is more and this console
 * will not fetch it* and *this log is too dense to page through* are three
 * different answers and only the first is an ending. `note` is the sentence for
 * each, composed server-side so that curl and the console say the same words -
 * the beginning one never says "the container started here", because the kubelet
 * rotates.
 */
export type LogPage = Schemas['LogPage'];

/** One live port-forward. `scheme` is the server's answer and is drawn, never
 *  re-derived: a copy of `internal/forward/scheme.go`'s table in the browser
 *  would be a second answer to the same question. */
export type Forward = Schemas['Forward'];
export type ForwardRequest = Schemas['ForwardRequest'];
/** A forward's flow UI in a window of the desktop's own (#65). */
export type ForwardWindowRequest = Schemas['ForwardWindowRequest'];
